// Source for the Vercel function api/app-release.js (generated by scripts/build-api.mjs: esbuild bundles this, its
// .ts imports and `jose` into one self-contained ESM file — see build-api.mjs for why it lives outside api/).
//
// Called by .github/workflows/app-release.yml when Vercel marks a PRODUCTION deployment successful, with
// `{ version, sha }` (the APP_VERSION of the deployed commit). Records the release in public.app_releases, which
// tells signed-in tabs to prompt for a reload (supabase/migrations/0015_app_releases.sql).
//
// Auth: the GitHub Actions OIDC token of that very workflow run — no stored secret. It must be signed by GitHub,
// issued for this audience, and carry this repository, a `deployment_status` event and this workflow.
//
// Codes: 401 bad token · 400 bad body · 405 not POST · 409 this deployment is not `version` yet (the production
// domain still serves the previous one; the workflow retries) · 500 not configured / insert failed · 200 recorded.
//
// Env (Vercel project settings, server-side): SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY.
import type { VercelRequest, VercelResponse } from '@vercel/node';
import { createClient } from '@supabase/supabase-js';
import { createRemoteJWKSet, jwtVerify, type JWTVerifyGetKey } from 'jose';
// Bundled: this is THIS deployment's version, which is what the liveness check compares against.
import { APP_VERSION } from '../../config/appVersion.ts';

const ISSUER = 'https://token.actions.githubusercontent.com';
const AUDIENCE = 'toprentals-app-release';
const REPOSITORY = 'sumar21/TopRentals';
const WORKFLOW_PREFIX = `${REPOSITORY}/.github/workflows/app-release.yml@`;
const VERSION_FORMAT = /^v\d{8}_\d+\.\d+\.\d+$/;
const SHA_FORMAT = /^[0-9a-f]{40}$/;

// Created on first use and kept at module level: a warm instance does not refetch GitHub's keys.
let githubKeys: JWTVerifyGetKey | null = null;
const keys = (): JWTVerifyGetKey => (githubKeys ??= createRemoteJWKSet(new URL(`${ISSUER}/.well-known/jwks`)));

/** Why `token` is not a token of this repository's workflow (for the log, never the response), or null if it is. */
async function rejectionReason(token: string): Promise<string | null> {
  let claims: Record<string, unknown>;
  try {
    ({ payload: claims } = await jwtVerify(token, keys(), {
      issuer: ISSUER,
      audience: AUDIENCE,
      algorithms: ['RS256'],
      clockTolerance: 30, // seconds: GitHub's clock and the function's differ
    }));
  } catch (error) {
    const { code } = (error ?? {}) as { code?: unknown };
    return typeof code === 'string' ? code : 'invalid token';
  }
  if (claims.repository !== REPOSITORY) return `repository ${String(claims.repository)}`;
  if (claims.event_name !== 'deployment_status') return `event_name ${String(claims.event_name)}`;
  if (typeof claims.workflow_ref !== 'string' || !claims.workflow_ref.startsWith(WORKFLOW_PREFIX)) {
    return `workflow_ref ${String(claims.workflow_ref)}`;
  }
  return null;
}

export default async function handler(req: VercelRequest, res: VercelResponse): Promise<void> {
  res.setHeader('Cache-Control', 'no-store');
  if (req.method !== 'POST') {
    res.setHeader('Allow', 'POST');
    res.status(405).json({ error: 'Method not allowed' });
    return;
  }

  // Token first: without a valid one nothing is said about the body.
  const token = /^Bearer\s+(\S+)$/i.exec(req.headers.authorization ?? '')?.[1];
  const rejected = token ? await rejectionReason(token) : 'no bearer token';
  if (rejected !== null) {
    console.warn(`[app-release] rejected: ${rejected}`);
    res.status(401).json({ error: 'Unauthorized' });
    return;
  }

  const { version, sha } = (req.body ?? {}) as { version?: unknown; sha?: unknown };
  if (typeof version !== 'string' || !VERSION_FORMAT.test(version) || typeof sha !== 'string' || !SHA_FORMAT.test(sha)) {
    res.status(400).json({ error: 'Expected { version, sha }' });
    return;
  }

  // The production domain may still be serving the previous deployment: say so, and the workflow asks again.
  if (version !== APP_VERSION) {
    console.log(`[app-release] not live yet: asked ${version} (${sha}), this deployment runs ${APP_VERSION}`);
    res.status(409).json({ error: 'NOT_LIVE_YET' });
    return;
  }

  try {
    const url = process.env.SUPABASE_URL;
    const key = process.env.SUPABASE_SERVICE_ROLE_KEY;
    if (!url || !key) throw new Error('SUPABASE_URL / SUPABASE_SERVICE_ROLE_KEY are not set');
    const supabase = createClient(url, key, { auth: { persistSession: false } });
    // A redeploy of a recorded (version, commit) is not an error: the duplicate is ignored.
    const { error } = await supabase
      .from('app_releases')
      .upsert({ version, commit_sha: sha }, { onConflict: 'version,commit_sha', ignoreDuplicates: true });
    if (error) throw new Error(error.message);
    console.log(`[app-release] recorded ${version} (${sha})`);
    res.status(200).json({ ok: true, version });
  } catch (err) {
    console.error('[app-release] insert failed:', err instanceof Error ? err.message : err);
    res.status(500).json({ error: 'Could not record the release' });
  }
}
